export function makeDiamond(character: string): string {
  if (character.length !== 1) throw new Error('Input must be a single character');
  const n = character.charCodeAt(0) - 'A'.charCodeAt(0);
  const rows = (n * 2 - 1);
  const mid = Math.floor(rows / 2);
  let result = '';
  for (let i = 0; i < rows; i++) {
    const spaces = ' '.repeat(mid - i);
    const letters = character.repeat(2 * i + 1);
    result += spaces + letters + spaces + '\n';
  }
  return result.trim();
}

